<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue';import{Message,Modal}from'@arco-design/web-vue';import{adminApi,type AdminChatMessage}from'@/api/admin';import{PublicApiError}from'@/api/client';import{formatDate,optionalPositiveInt,safeJSON}from'@/utils/format'
const rows=ref<AdminChatMessage[]>([]),loading=ref(false),hasMore=ref(false),next=ref(0),detail=ref<AdminChatMessage|null>(null);const filters=reactive({userId:'',senderId:'',receiverId:''})
function report(e:unknown){Message.error(e instanceof PublicApiError?e.message:'请求失败')};async function load(append=false){loading.value=true;try{const page=await adminApi.chats({beforeId:append?next.value:undefined,limit:50,userId:optionalPositiveInt(filters.userId),sendUserId:optionalPositiveInt(filters.senderId),revUserId:optionalPositiveInt(filters.receiverId)});rows.value=append?[...rows.value,...page.list]:page.list;hasMore.value=page.hasMore;next.value=page.nextBeforeId}catch(e){report(e)}finally{loading.value=false}}
function remove(row:AdminChatMessage){Modal.warning({title:'删除私聊消息',content:`确认移除消息 #${row.id}？该操作会保留幂等 tombstone 并修复会话指针。`,hideCancel:false,onOk:async()=>{try{await adminApi.deleteChatMessage(row.id);Message.success('消息已删除');await load()}catch(e){report(e)}}})};onMounted(()=>load())
</script>
<template><section class="page-stack"><a-card :bordered="false"><div class="toolbar"><div><h2>私聊记录</h2><p>按用户/发送方/接收方审计；消息详情使用纯文本 JSON 安全渲染。</p></div><a-space wrap><a-input v-model="filters.userId" placeholder="任一用户 ID"/><a-input v-model="filters.senderId" placeholder="发送方 ID"/><a-input v-model="filters.receiverId" placeholder="接收方 ID"/><a-button type="primary" @click="load()">查询</a-button></a-space></div></a-card><a-card :bordered="false"><a-table row-key="id" :data="rows" :loading="loading" :pagination="false"><template #columns><a-table-column title="ID" data-index="id" :width="80"/><a-table-column title="发送方"><template #cell="{record}">{{record.sender.nickname}} (#{{record.sender.id}})</template></a-table-column><a-table-column title="接收方"><template #cell="{record}">{{record.receiver.nickname}} (#{{record.receiver.id}})</template></a-table-column><a-table-column title="类型" data-index="messageType" :width="80"/><a-table-column title="预览" data-index="preview"/><a-table-column title="时间" :width="180"><template #cell="{record}">{{formatDate(record.createdAt)}}</template></a-table-column><a-table-column title="操作" :width="150"><template #cell="{record}"><a-space><a-button size="small" @click="detail=record">详情</a-button><a-button size="small" status="danger" @click="remove(record)">删除</a-button></a-space></template></a-table-column></template></a-table><div class="load-more"><a-button v-if="hasMore" @click="load(true)">加载更多</a-button></div></a-card><a-modal :visible="detail!==null" title="消息详情" :footer="false" @cancel="detail=null"><pre class="safe-json">{{safeJSON(detail?.message)}}</pre></a-modal></section></template>
